const WebUiAsset* find_webui_asset(std::string_view path) {
  if (path.empty() || path == "/" || path == "/chat" || path == "/ui") {
    path = "/index.html";
  }
  const auto it = std::lower_bound(
      std::begin(kWebUiAssets), std::end(kWebUiAssets), path,
      [](const WebUiAsset& a, std::string_view p) { return a.path < p; });
  if (it != std::end(kWebUiAssets) && it->path == path) return &*it;
  return nullptr;
}

